// NULL-tolerant scan buffer for productVariantScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type productVariantPreloadBuf struct {
	ID             sql.Null[uuid.UUID]
	HouseholdID    sql.Null[uuid.UUID]
	ConceptID      sql.Null[uuid.UUID]
	Name           sql.Null[string]
	NormalizedName sql.Null[string]
	Brand          sql.Null[string]
	PackageSize    sql.Null[string]
	Barcode        sql.Null[string]
	Archived       sql.Null[bool]
	Revision       sql.Null[int64]
	CreatedAt      sql.Null[time.Time]
	UpdatedAt      sql.Null[time.Time]
}

// productVariantScanMapperNullable maps the preloaded productVariant
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func productVariantScanMapperNullable(prefix string) scan.Mapper[*ProductVariant] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*ProductVariant, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *productVariantPreloadBuf) any
		}
		targets := make([]target, 0, 12)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.HouseholdID }})
			case "concept_id":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.ConceptID }})
			case "name":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.Name }})
			case "normalized_name":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.NormalizedName }})
			case "brand":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.Brand }})
			case "package_size":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.PackageSize }})
			case "barcode":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.Barcode }})
			case "archived":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.Archived }})
			case "revision":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.Revision }})
			case "created_at":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *productVariantPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(productVariantPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*ProductVariant, error) {
				buf := link.(*productVariantPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.ConceptID.Valid) &&
					!(buf.Name.Valid) &&
					!(buf.NormalizedName.Valid) &&
					!(buf.Brand.Valid) &&
					!(buf.PackageSize.Valid) &&
					!(buf.Barcode.Valid) &&
					!(buf.Archived.Valid) &&
					!(buf.Revision.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.UpdatedAt.Valid) {
					return nil, nil
				}

				o := new(ProductVariant)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.ConceptID.Valid {
					o.ConceptID = buf.ConceptID.V
				}
				if buf.Name.Valid {
					o.Name = buf.Name.V
				}
				if buf.NormalizedName.Valid {
					o.NormalizedName = buf.NormalizedName.V
				}
				if buf.Brand.Valid {
					o.Brand = buf.Brand.V
				}
				if buf.PackageSize.Valid {
					o.PackageSize = buf.PackageSize.V
				}
				o.Barcode = buf.Barcode
				if buf.Archived.Valid {
					o.Archived = buf.Archived.V
				}
				if buf.Revision.Valid {
					o.Revision = buf.Revision.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				if buf.UpdatedAt.Valid {
					o.UpdatedAt = buf.UpdatedAt.V
				}
				return o, nil
			}
	}
}

func (o *ProductVariant) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AllocationRules":
		rels, ok := retrieved.(AllocationRuleSlice)
		if !ok {
			return fmt.Errorf("productVariant cannot load %T as %q", retrieved, name)
		}

		o.R.AllocationRules = rels
		o.R.Loaded.AllocationRules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductVariant = o
				rel.R.Loaded.ProductVariant = true
			}
		}
		return nil
	case "ProductAliases":
		rels, ok := retrieved.(ProductAliasSlice)
		if !ok {
			return fmt.Errorf("productVariant cannot load %T as %q", retrieved, name)
		}

		o.R.ProductAliases = rels
		o.R.Loaded.ProductAliases = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductVariant = o
				rel.R.Loaded.ProductVariant = true
			}
		}
		return nil
	case "ProductCorrections":
		rels, ok := retrieved.(ProductCorrectionSlice)
		if !ok {
			return fmt.Errorf("productVariant cannot load %T as %q", retrieved, name)
		}

		o.R.ProductCorrections = rels
		o.R.Loaded.ProductCorrections = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductVariant = o
				rel.R.Loaded.ProductVariant = true
			}
		}
		return nil
	case "ProductConcept":
		rel, ok := retrieved.(*ProductConcept)
		if !ok {
			return fmt.Errorf("productVariant cannot load %T as %q", retrieved, name)
		}

		o.R.ProductConcept = rel
		o.R.Loaded.ProductConcept = true

		if rel != nil {
			rel.R.ProductVariants = ProductVariantSlice{o}
		}
		return nil
	case "PurchaseItems":
		rels, ok := retrieved.(PurchaseItemSlice)
		if !ok {
			return fmt.Errorf("productVariant cannot load %T as %q", retrieved, name)
		}

		o.R.PurchaseItems = rels
		o.R.Loaded.PurchaseItems = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductVariant = o
				rel.R.Loaded.ProductVariant = true
			}
		}
		return nil
	default:
		return fmt.Errorf("productVariant has no relationship %q", name)
	}
}

